{"path": "solution.py", "content": "def add_days(date_str, n):
    """add_days('2026-01-31', 3) == '2026-02-03'."""
    def is_leap_year(year):
        # Leap year: divisible by 4, except centuries unless divisible by 400
        if year % 400 == 0:
            return True
        if year % 100 == 0:
            return False
        if year % 4 == 0:
            return True
        return False

    def days_in_month(year, month):
        if month in [1, 3, 5, 7, 8, 10, 12]:
            return 31
        elif month in [4, 6, 9, 11]:
            return 30
        elif month == 2:
            return 29 if is_leap_year(year) else 28

    # Parse the input date
    year, month, day = map(int, date_str.split('-'))

    # Handle positive n (add days)
    if n > 0:
        while n > 0:
            days_in_current_month = days_in_month(year, month)
            days_remaining_in_month = days_in_current_month - day

            if n > days_remaining_in_month:
                # Move to next month
                n -= (days_remaining_in_month + 1)
                day = 1
                month += 1
                if month > 12:
                    month = 1
                    year += 1
            else:
                # Add remaining days in current month
                day += n
                n = 0

    # Handle negative n (subtract days)
    elif n < 0:
        n = -n  # Work with positive value
        while n > 0:
            if day > n:
                # Subtract days within current month
                day -= n
                n = 0
            else:
                # Need to go to previous month
                n -= day
                month -= 1
                if month < 1:
                    month = 12
                    year -= 1
                day = days_in_month(year, month)

    # Format the result
    return f"{year:04d}-{month:02d}-{day:02d}""}

