    year, month, day = map(int, date_str.split('-'))

    # Handle positive n (add days)
    if n >= 0:
        for _ in range(n):
            day += 1
            if day > days_in_month(year, month):
                day = 1
                month += 1
                if month > 12:
                    month = 1
                    year += 1
    else:
        # Handle negative n (subtract days)
        for _ in range(-n):
            day -= 1
            if day < 1:
                month -= 1
                if month < 1:
                    month = 12
                    year -= 1
                day = days_in_month(year, month)

