def days_in_month(year, month):
    """Return the number of days in a given month of a given year."""
    if month in [1, 3, 5, 7, 8, 10, 12]:
        return 31
    elif month in [4, 6, 9, 11]:
        return 30
    elif month == 2:
        return 29 if is_leap_year(year) else 28
    return 0

def add_days(date_str, n):
    """add_days('2026-01-31', 3) == '2026-02-03'."""
    # Parse the input date
    year, month, day = map(int, date_str.split('-'))

    # Handle negative n by subtracting days
    if n < 0:
        n = -n
        # Subtract days
        while n > 0:
            days_in_current_month = days_in_month(year, month)
            if day > n:
                day -= n
                n = 0
            else:
                n -= day
                day = 0
                month -= 1
                if month == 0:
                    month = 12
                    year -= 1
                day = days_in_month(year, month)
    else:
        # Add days
        while n > 0:
            days_in_current_month = days_in_month(year, month)
            remaining_days_in_month = days_in_current_month - day
            if n <= remaining_days_in_month:
                day += n
                n = 0
            else:
                n -= (remaining_days_in_month + 1)
                day = 1
                month += 1
                if month > 12:
                    month = 1
                    year += 1

    # Format the result as 'YYYY-MM-DD'
    return f"{year:04d}-{month:02d}-{day:02d}"

