    """add_days('2026-01-31', 3) == '2026-02-03'."""
    year, month, day = map(int, date_str.split('-'))

    # Days in each month (index 1-12)
    def days_in_month(y, m):
        if m in (1, 3, 5, 7, 8, 10, 12):
            return 31
        elif m in (4, 6, 9, 11):
            return 30
        elif m == 2:
            if is_leap(y):
                return 29
            else:
                return 28

    def is_leap(y):
        if y % 400 == 0:
            return True
        if y % 100 == 0:
            return False
        if y % 4 == 0:
            return True
        return False

    # Convert to day-of-year, then add n, then convert back
    # But simpler: just increment/decrement day by day
    # Actually, let's do it more efficiently by working with total days

    # Convert date to a day number (days since some epoch)
    # We'll use a simple approach: count days from year 1, month 1, day 1

    def date_to_days(y, m, d):
        total = 0
        # Days from complete years
        for yy in range(1, y):
            total += 366 if is_leap(yy) else 365
        # Days from complete months in current year
        for mm in range(1, m):
            total += days_in_month(y, mm)
        # Days in current month
        total += d
        return total

    def days_to_date(total):
        # Find year
        y = 1
        while True:
            year_days = 366 if is_leap(y) else 365
            if total <= year_days:
                break
            total -= year_days
            y += 1
        # Find month
        m = 1
        while True:
            month_days = days_in_month(y, m)
            if total <= month_days:
                break
            total -= month_days
            m += 1
        d = total
        return y, m, d

    total = date_to_days(year, month, day) + n
    y, m, d = days_to_date(total)
    return f"{y:04d}-{m:02d}-{d:02d}""}

