        total = 0
        for yy in range(y):
            total += 366 if is_leap(yy) else 365
        for mm in range(1, m):
            total += days_in_month(y, mm)
        total += d - 1
        return total

    def days_to_date(total):
        y = 0
        while True:
            dy = 366 if is_leap(y) else 365
            if total < dy:
                break
            total -= dy
            y += 1
        m = 1
        while True:
            dm = days_in_month(y, m)
            if total < dm:
                break
            total -= dm
            m += 1
        d = total + 1
        return y, m, d

    total = date_to_days(year, month, day) + n
    y, m, d = days_to_date(total)
    return f"{y:04d}-{m:02d}-{d:02d}""}

