        if m in (1, 3, 5, 7, 8, 10, 12):
            return 31
        elif m in (4, 6, 9, 11):
            return 30
        else:  # February
            if y % 400 == 0:
                return 29
            elif y % 100 == 0:
                return 28
            elif y % 4 == 0:
                return 29
            else:
                return 28

    # Convert date to days since a reference point, then add n, then convert back
    # We'll use a day-count approach: count total days from year 0

    def is_leap(y):
        if y % 400 == 0:
            return True
        if y % 100 == 0:
            return False
        if y % 4 == 0:
            return True
        return False

    def days_before_year(y):
        """Number of days from year 0 to start of year y."""
        # Years 1 to y-1
        y -= 1
        return y * 365 + y // 4 - y // 100 + y // 400

    def days_before_month(y, m):
        """Number of days from start of year y to start of month m."""
        dim = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        total = sum(dim[:m])
        if m > 2 and is_leap(y):
            total += 1
        return total

    # Convert to absolute day number
    total_days = days_before_year(year) + days_before_month(year, month) + day + n

    # Convert back to date
    # Find year
    y = 1
    # Estimate year
    y = total_days // 366  # rough lower bound
    while days_before_year(y + 1) < total_days:
        y += 1
    while days_before_year(y) >= total_days:
        y -= 1

    remaining = total_days - days_before_year(y)

    # Find month
    m = 1
    while m <= 12:
        dim = days_in_month(y, m)
        if remaining <= dim:
            break
        remaining -= dim
        m += 1

    d = remaining

    return f"{y:04d}-{m:02d}-{d:02d}""}

